    (h1, v1), (h2, v2) = cells[i], cells[j]
    if v1 == v2 and abs(h1 - h2) == 1:
        return True
    if h1 == h2 and abs(v1 - v2) == 1:
        lo = min(v1, v2)
        return (h1 + lo) % 2 == 1
    return False

def edge_info(i, j):
