            pen += 50
            continue
        if L < 18:
            pen += (18 - L) * 3
        if L > 60:
            pen += (L - 60) * 3
        if L < 24 or L > 50:
            pen += 1
    # coverage of each edge
    for e, (a, b, t) in enumerate(edges):
        offs = sorted(o for (ee, o) in xs if ee == e)
        if not offs:
            pen += 100; continue
