    xs = set()
    for e, cl in enumerate(cand):
        last = -100
        for o in cl:
            if o - last >= 18:
                xs.add((e, o)); last = o
    nicks = set()
    cur, _, _, _ = penalty(xs, nicks)
    best = (cur, set(xs), set(nicks))
    for it in range(iters):
        T = 2.0 * (1 - it / iters) + 0.02
        xs2 = set(xs); nk2 = set(nicks)
        r = rnd.random()
        if r < 0.6:
            e = rnd.randrange(len(edges))
            if not cand[e]:
                continue
            o = rnd.choice(cand[e])
            if (e, o) in xs2:
                xs2.remove((e, o))
            else:
                xs2.add((e, o))
        else:
            h = rnd.randrange(N)
            o = rnd.randrange(lo[h] + 8, hi[h] - 8)
            if (h, o) in nk2:
                nk2.remove((h, o))
            else:
                nk2.add((h, o))
