        if p2 <= cur or rnd.random() < math.exp(-(p2 - cur) / T):
            xs, nicks, cur = xs2, nk2, p2
            if cur < best[0]:
                best = (cur, set(xs), set(nicks))
    return best

best = None
for seed in range(6):
    b = run_sa(seed)
    print("seed", seed, "penalty", round(b[0], 2), "xs", len(b[1]), "nicks", len(b[2]))
    if best is None or b[0] < best[0]:
        best = b
    if best[0] == 0:
        break

pen, xs, nicks = best[0], best[1], best[2]
pen, segs, nb, comps = penalty(xs, nicks)
print("final penalty", pen)

# ---- 3. build design ----
helices = [sc.Helix(max_offset=max(hi.values()) + 1, grid_position=cells[i]) for i in range(N)]
design = sc.Design(helices=helices, strands=[], grid=sc.honeycomb)

scaf_domains = []
for k in range(K):
    h = path[k]
    scaf_domains.append(sc.Domain(helix=h, forward=(par(h) == 0), start=lo[h], end=hi[h]))
design.add_strand(sc.Strand(domains=scaf_domains, is_scaffold=True))

# staples: walk each path component from its 5' end
done = set()
staple_info = []
for comp in comps:
    ends = [x for x in comp if len(nb[x]) < 2]
    if len(comp) == 1:
        start = comp[0]
    else:
        start = None
        for x in ends:
            h, s, e = segs[x]
            fwd = par(h) == 1
            # free side of x
            free_low = not any(False for _ in [0])
            # determine which side is free: junction sides
            # side low is junction if there exists a crossover at s on h (i.e. by_start partner)
            has_low = any(segs[y][1] == s and segs[y][0] != h for y in nb[x])
            has_high = any(segs[y][2] == e and segs[y][0] != h for y in nb[x])
            # 5' side: fwd -> low, rev -> high
